import type { BuildTask, Lesson } from '../types';
import { diagram, formula, list, note, p, sim, table, warn } from './helpers';

const M = 'foundations';
const work = (ms: number): BuildTask['overrides'] => [
  { kinds: ['server', 'containerService'], config: { processingLatencyMs: String(ms) }, reason: `Each request needs ${ms} ms of application work, wherever it runs.` },
  { kinds: ['serverless'], config: { executionMs: String(ms) }, reason: `Functions run the same ${ms} ms of work.` },
];

